227	    #[test]
228	    fn read_failure_is_typed_error_not_digest() {
229	        struct FailingReader;
230	        impl Read for FailingReader {
231	            fn read(&mut self, _buf: &mut [u8]) -> io::Result<usize> {
232	                Err(io::Error::new(io::ErrorKind::Other, "boom"))
233	            }
234	        }
235	        let err = digest_reader(FailingReader).unwrap_err();
236	        assert!(err.to_string().contains("boom"));
