239	    /// 按给定片段长度序列依次返回输入字节的读取器；序列为空时每次读满。
240	    /// 用于模拟不同分块方式，验证摘要只取决于字节内容而非读取方式。
241	    struct ChunkedReader<'a> {
242	        data: &'a [u8],
243	        pos: usize,
244	        chunk_sizes: &'a [usize],
245	        chunk_index: usize,
246	    }
247	
248	    impl<'a> ChunkedReader<'a> {
249	        fn new(data: &'a [u8], chunk_sizes: &'a [usize]) -> Self {
250	            ChunkedReader { data, pos: 0, chunk_sizes, chunk_index: 0 }
251	        }
252	    }
253	
254	    impl Read for ChunkedReader<'_> {
255	        fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
256	            if self.pos == self.data.len() {
257	                return Ok(0);
258	            }
259	            let mut limit = buf.len();
260	            if !self.chunk_sizes.is_empty() {
261	                limit = limit.min(self.chunk_sizes[self.chunk_index % self.chunk_sizes.len()]);
262	                self.chunk_index += 1;
263	            }
264	            let n = limit.min(self.data.len() - self.pos);
265	            buf[..n].copy_from_slice(&self.data[self.pos..self.pos + n]);
266	            self.pos += n;
267	            Ok(n)
268	        }
269	    }
270	
271	    /// 确定性长输入：长度 3*64KiB + 1234，保证跨越多次内部读取且末尾留有不整段的尾巴。
272	    fn long_input() -> Vec<u8> {
273	        (0..(3 * 64 * 1024 + 1234))
274	            .map(|i| ((i * 31 + 7) % 256) as u8)
275	            .collect()
276	    }
277	
278	    /// 独立依据：python3 hashlib.sha256 对 long_input() 全部字节的计算结果。
279	    const LONG_INPUT_HEX: &str =
280	        "8ca02b16ce35f9fca993a0fdf5a537fc72a62a77b2e6fa852a371f18b8e3fcc4";
281	
282	    #[test]
283	    fn long_input_digest_covers_all_bytes_including_tail() {
284	        let digest = digest_reader(&long_input()[..]).unwrap();
285	        assert_eq!(digest.to_hex(), LONG_INPUT_HEX);
286	    }
