301	/// 解析用户给出的预期摘要。
302	///
303	/// 解析规则完全来自库（[`Sha256Digest::from_hex_bytes`]），与库的
304	/// `FromStr` 以及摘要的再次显示共用同一套实现：必须恰好是 64 个 ASCII
305	/// 十六进制字符（大小写均可），按其表示的 32 字节摘要值比较，不做任何
306	/// 空白裁剪——前缀、空格、末尾换行、长度不对或含非十六进制字符都视为
307	/// 格式错误；参数无法解码为合法文字时，直接按其原始字节校验，同样视为
308	/// 格式错误。这里只负责把库的类型化错误映射为本命令既有的提示文字。
309	fn parse_expected_digest(arg: &OsStr) -> Result<Sha256Digest, String> {
310	    Sha256Digest::from_hex_bytes(arg.as_encoded_bytes()).map_err(|err| match err {
311	        ParseDigestError::InvalidLength(len) => format!(
312	            "expected digest must be exactly 64 ASCII hexadecimal characters, got {len}"
313	        ),
314	        ParseDigestError::InvalidHexChar(_) => {
315	            "expected digest contains a non-hexadecimal character".to_string()
316	        }
317	    })
318	}
319	
320	fn run_check_digest(path: &Path, expected_arg: &OsStr) -> ExitCode {
321	    // 先校验摘要格式；格式不合法时绝不打开文件——即使路径本身也不存在，
322	    // 仍报告摘要格式问题。
323	    let expected = match parse_expected_digest(expected_arg) {
324	        Ok(digest) => digest,
325	        Err(reason) => {
326	            return emit_error(
327	                2,
328	                format!("inkseal: invalid expected digest: {reason}\n{USAGE}\n").as_bytes(),
329	            );
330	        }
331	    };
332	
333	    finish_digest_check(path, expected)
334	}
335	
336	/// 预期摘要已确认合法后，核对 `path` 的实际内容并按既有的唯一一套规则
337	/// 输出：匹配写 `OK\n`（完整交付后以 0 退出）；访问失败报告文件原因；
338	/// 不匹配列出小写的预期与实际摘要。`check-digest` 与
339	/// `check-digest-file` 在拿到合法摘要之后共用本函数，因此两者对待核对
340	/// 文件的原始字节、流式读取、比较与输出规则完全一致。
341	fn finish_digest_check(path: &Path, expected: Sha256Digest) -> ExitCode {
342	    // 与 digest 共用同一条文件访问规则；访问失败是文件问题，
343	    // 绝不能被解释成内容不匹配。
344	    let actual = match digest_file(path) {
345	        Ok(digest) => digest,
346	        Err(err) => return emit_error(1, err.message().as_bytes()),
347	    };
348	
349	    if actual == expected {
350	        emit_success(b"OK\n")
351	    } else {
352	        // 内容不匹配：预期与实际都用库的同一显示规则呈现为
353	        // 64 个小写十六进制字符（大小写混用的输入也规范为小写）。
354	        emit_error(
355	            1,
356	            format!(
357	                "inkseal: digest mismatch for '{}'\n\
358	                 expected: {}\n\
359	                 actual:   {}\n",
360	                path_display(path),
361	                expected.to_hex(),
362	                actual.to_hex()
363	            )
364	            .as_bytes(),
365	        )
366	    }
367	}
368	
369	/// 读取并解析摘要文件时的失败。
370	///
371	/// [`Access`](Self::Access) 是摘要文件本身的访问问题（打不开或读取中途
372	/// 失败，以 `1` 退出），直接复用三条命令共用的 [`FileAccessError`]——它
373	/// 已带 [`FileRole::DigestFile`]，因此提示会明确对象是摘要文件，又与内容
374	/// 文件遵循同一条打开/读取分类规则。[`Malformed`](Self::Malformed) 是内容
375	/// 不符合“恰好一份摘要”的格式约定（以 `2` 退出）。两类都必须在待核对
376	/// 文件被访问之前判定，且提示里都要带上摘要文件自己的路径，绝不能把摘要
377	/// 文件的问题改报成待核对文件的访问错误。
378	enum DigestFileError {
379	    /// 摘要文件无法打开或读取中途失败（含路径指向目录时的读取错误）。
380	    Access(FileAccessError),
381	    /// 摘要文件内容不符合格式约定。
382	    Malformed(PathBuf, DigestFileProblem),
383	}
384	
385	/// 摘要文件内容的具体格式问题，用于给出精确的错误原因。
386	enum DigestFileProblem {
387	    /// 空文件：连一个摘要字符都没有。
388	    Empty,
389	    /// 内容超过“64 个十六进制字符 + 单个 CRLF”的 66 字节上限：
390	    /// 多余字节可能是第二份摘要、文件名或任何附加内容，一律拒绝。
391	    TooLong,
392	    /// 去掉唯一允许的末尾换行后，摘要正文未通过库的严格十六进制解析。
393	    InvalidDigest(ParseDigestError),
394	}
395	
396	impl DigestFileProblem {
397	    /// 渲染为人类可读的具体格式原因（不含路径，路径由调用方添加）。
398	    fn description(&self) -> String {
399	        const RULE: &str = concat!(
400	            "the digest file must contain exactly one digest of 64 ASCII ",
401	            "hexadecimal characters, optionally followed by one LF or CRLF"
402	        );
403	        match self {
404	            DigestFileProblem::Empty => {
405	                format!("{RULE}, but the file is empty")
406	            }
407	            DigestFileProblem::TooLong => {
408	                format!("{RULE}, but the file contains extra bytes beyond that single line")
409	            }
410	            DigestFileProblem::InvalidDigest(ParseDigestError::InvalidLength(len)) => {
411	                format!(
412	                    "{RULE}; the digest text is {len} bytes long (before any trailing newline)"
413	                )
414	            }
415	            DigestFileProblem::InvalidDigest(ParseDigestError::InvalidHexChar(pos)) => {
416	                format!(
417	                    "{RULE}; the digest text contains a non-hexadecimal byte at offset {pos} \
418	                    (only 0-9, a-f and A-F are allowed)"
419	                )
420	            }
421	        }
422	    }
423	}
424	
425	/// 打开摘要文件、读取其（被严格限长的）全部内容并解析为摘要值。
426	///
427	/// 合法文件至多 66 字节：64 个十六进制字符，末尾可带一个 LF 或 CRLF。
428	/// 这里最多读入 67 字节——多出的第 67 字节是“内容超长”的确定性哨兵，
429	/// 因此内存占用恒定，也不必把可能很大的非法文件（例如误指向二进制或
430	/// 第二份摘要）整个读完就能判定格式错误。读取本身失败与内容格式不合法
431	/// 是两类不同的失败，分别映射到 [`DigestFileError`] 的不同变体。
432	fn load_expected_digest_file(path: &Path) -> Result<Sha256Digest, DigestFileError> {
433	    use std::io::Read as _;
434	
435	    let file = File::open(path).map_err(|err| {
436	        DigestFileError::Access(FileAccessError::open(FileRole::DigestFile, path, err))
437	    })?;
438	
439	    let mut content = Vec::with_capacity(67);
440	    file.take(67)
441	        .read_to_end(&mut content)
442	        .map_err(|err| {
443	            DigestFileError::Access(FileAccessError::read(
444	                FileRole::DigestFile,
445	                path,
446	                ReadError::Plain(err),
447	            ))
448	        })?;
449	
450	    parse_digest_file_content(&content)
451	        .map_err(|problem| DigestFileError::Malformed(path.to_path_buf(), problem))
452	}
453	
454	/// 摘要文件内容的唯一解析规则。
455	///
456	/// 与 `check-digest` 的摘要参数不同，摘要文件允许结尾带一个换行：内容
457	/// 要么恰好是 64 个十六进制字符，要么在其后紧跟一个 LF 或 CRLF。除此之外
458	/// 不做任何裁剪或修正——空文件、首尾空格、单独的 CR、额外空行、第二份
459	/// 摘要、附带的文件名、`0x` 前缀或非 ASCII 字节都属于格式错误。剥离唯一
460	/// 允许的行结束后，正文仍必须通过库的严格解析
461	/// （[`Sha256Digest::from_hex_bytes`]），其严格格式不在此放宽。
462	fn parse_digest_file_content(content: &[u8]) -> Result<Sha256Digest, DigestFileProblem> {
463	    if content.is_empty() {
464	        return Err(DigestFileProblem::Empty);
465	    }
466	    if content.len() > 66 {
467	        return Err(DigestFileProblem::TooLong);
468	    }
469	
470	    // 仅当 LF 是最后一个字节时剥离它；剥到 LF 后，再仅当 CR 紧接在它
471	    // 前面（即结尾确为 CRLF）时剥离该 CR。顺序保证：单独的 CR、CRLF
472	    // 之外的任何尾随字节都不会被裁掉——例如 "\n\r" 的末字节是 CR，
473	    // 第一步就不匹配，整体按长度错误拒绝。
474	    let mut hex: &[u8] = content;
475	    if let Some(rest) = hex.strip_suffix(b"\n") {
476	        hex = rest;
477	        if let Some(rest) = hex.strip_suffix(b"\r") {
478	            hex = rest;
479	        }
480	    }
481	
482	    Sha256Digest::from_hex_bytes(hex).map_err(DigestFileProblem::InvalidDigest)
483	}
484	
485	fn run_check_digest_file(path: &Path, digest_path: &Path) -> ExitCode {
486	    // 先完整处理摘要文件：在它被成功打开、读取并确认格式合法之前，
487	    // 绝不访问待核对文件——即使待核对文件不存在，也不得改报它的错误。
488	    let expected = match load_expected_digest_file(digest_path) {
489	        Ok(digest) => digest,
490	        // 打不开与读取中途失败共用内容文件那一条提示规则，只是对象被
491	        // 明确标注为摘要文件；两者都以退出码 1 结束，不进入内容比较。
492	        Err(DigestFileError::Access(err)) => {
493	            return emit_error(1, err.message().as_bytes());
494	        }
495	        Err(DigestFileError::Malformed(p, problem)) => {
496	            return emit_error(
497	                2,
498	                format!(
499	                    "inkseal: malformed digest file '{}': {}\n{USAGE}\n",
500	                    path_display(&p),
501	                    problem.description()
502	                )
503	                .as_bytes(),
504	            );
505	        }
506	    };
507	
508	    // 摘要文件合法后才打开待核对文件；其后的访问、比较与输出规则与
509	    // check-digest 完全一致（共用 finish_digest_check）。
510	    finish_digest_check(path, expected)
511	}
512	
513	/// 生成可安全输出到标准错误的路径文本：不可解码的字节以替换字符
514	/// （U+FFFD）呈现，控制字符转义为可见写法。该文本只用于显示。
515	fn path_display(path: &Path) -> String {
516	    let lossy = path.to_string_lossy();
517	    if !lossy.contains(char::is_control) {
518	        return lossy.into_owned();
519	    }
520	    let mut out = String::with_capacity(lossy.len());
521	    for ch in lossy.chars() {
522	        match ch {
523	            '\t' => out.push_str("\\t"),
524	            '\n' => out.push_str("\\n"),
525	            '\r' => out.push_str("\\r"),
526	            c if c.is_control() => {
527	                use std::fmt::Write as _;
528	                let _ = write!(out, "\\u{{{:x}}}", c as u32);
529	            }
530	            c => out.push(c),
531	        }
532	    }
533	    out
534	}
535

