pub fn from_spki_der(der: &[u8]) -> Result<Ed25519PublicKey, ImportPublicKeyError> {
    let (tag, spki, rest) = read_tlv(der).ok_or(ImportPublicKeyError::Malformed)?;
    if tag != 0x30 || !rest.is_empty() { return Err(Malformed); }
    let (tag, alg, rest) = read_tlv(spki).ok_or(Malformed)?;
    if tag != 0x30 { return Err(Malformed); }
    let (tag, bit_string, rest) = read_tlv(rest).ok_or(Malformed)?;
    if tag != 0x03 || !rest.is_empty() { return Err(Malformed); }
    // 算法序列内部：恰好一个 OID，没有参数（NULL 也不行）
    let (tag, oid_content, rest) = read_tlv(alg).ok_or(Malformed)?;
    if tag != 0x06 || !rest.is_empty() { return Err(Malformed); }
    let arcs = decode_oid(oid_content).ok_or(Malformed)?;
    // 位串：未使用位数为零，内容恰好 32 字节
    let (&unused, key) = bit_string.split_first().ok_or(Malformed)?;
    if unused != 0 || key.len() != 32 { return Err(Malformed); }
    if arcs != [1, 3, 101, 112] {
        return Err(ImportPublicKeyError::UnsupportedAlgorithm(ObjectIdentifier::new(arcs)));
    }
    let mut bytes = [0u8; 32];
    bytes.copy_from_slice(key);
    Ok(Ed25519PublicKey(bytes))
}
